using System.Collections.Generic;
using UnityEngine;

namespace CCoop.Plugin.World
{
    /// <summary>
    /// Network ids for world objects in the current layer.
    ///
    /// Id spaces never overlap, so no peer ever has to ask another for an id:
    ///   1 .. 0x00FFFFFF          generated by the host when the layer was built
    ///   0x01000000 + p*64 + c    child c of structure placement p (replayed identically on every peer)
    ///   0x40000000 + peer<<24 + n  created at runtime by that peer (loot, drops, spawns)
    /// The runtime range also names the owner of a loose item's physics.
    /// </summary>
    internal static class EntityRegistry
    {
        internal const uint StructureBase = 0x01000000;
        internal const uint RuntimeBase = 0x40000000;
        internal const int RuntimeShift = 24;

        private static readonly Dictionary<uint, GameObject> ById = new Dictionary<uint, GameObject>();
        private static readonly Dictionary<int, uint> IdByInstance = new Dictionary<int, uint>();
        private static readonly Dictionary<uint, string> KeyById = new Dictionary<uint, string>();
        private static uint _nextRuntime;
        private static uint _nextGenerated = 1;

        internal static int Count => ById.Count;
        internal static IEnumerable<uint> Ids => ById.Keys;

        internal static void Clear()
        {
            ById.Clear();
            IdByInstance.Clear();
            KeyById.Clear();
            _nextRuntime = 0;
            _nextGenerated = 1;
        }

        internal static uint NextGeneratedId() => _nextGenerated++;

        internal static uint StructureId(int placement, int child) => StructureBase + (uint)placement * 64u + (uint)child;

        internal static uint AllocateRuntime(byte peer)
        {
            _nextRuntime++;
            return RuntimeBase + ((uint)peer << RuntimeShift) + (_nextRuntime & 0x00FFFFFF);
        }

        /// <summary>The peer that created a runtime object, or 0 (host) for everything else.</summary>
        internal static byte CreatorOf(uint id) =>
            id >= RuntimeBase ? (byte)((id - RuntimeBase) >> RuntimeShift) : (byte)0;

        internal static bool IsRuntime(uint id) => id >= RuntimeBase;

        internal static void Register(uint id, GameObject go, string key)
        {
            if (go == null) return;
            if (ById.TryGetValue(id, out var existing) && existing != null && existing != go)
                IdByInstance.Remove(existing.GetInstanceID());
            ById[id] = go;
            IdByInstance[go.GetInstanceID()] = id;
            KeyById[id] = key ?? "";
            if (id >= _nextGenerated && id < StructureBase) _nextGenerated = id + 1;
        }

        internal static bool TryGet(uint id, out GameObject go)
        {
            if (ById.TryGetValue(id, out go) && go != null) return true;
            go = null;
            return false;
        }

        internal static bool TryGetId(GameObject go, out uint id)
        {
            id = 0;
            return go != null && IdByInstance.TryGetValue(go.GetInstanceID(), out id) && ById.ContainsKey(id);
        }

        internal static string KeyOf(uint id) => KeyById.TryGetValue(id, out var k) ? k : null;

        internal static void Remove(uint id)
        {
            if (ById.TryGetValue(id, out var go) && go != null) IdByInstance.Remove(go.GetInstanceID());
            ById.Remove(id);
            KeyById.Remove(id);
        }

        /// <summary>Drops entries whose objects Unity has destroyed.</summary>
        internal static int Prune()
        {
            List<uint> dead = null;
            foreach (var kv in ById)
                if (kv.Value == null) (dead ?? (dead = new List<uint>())).Add(kv.Key);
            if (dead == null) return 0;
            foreach (var id in dead) { ById.Remove(id); KeyById.Remove(id); }
            return dead.Count;
        }

        internal static IEnumerable<KeyValuePair<uint, GameObject>> All => ById;
    }
}
